<?php
namespace Modules\Ran\Services;
use DomainException;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{ProductionOrder,MaterialIssue,ProductionReceipt,WastageEntry,StockLot};use Modules\Ran\Support\RanContext;
class ProductionService {public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private AuditService $audit){}
 public function create(array $data):ProductionOrder{return DB::transaction(function()use($data){$order=ProductionOrder::create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),['order_no'=>$this->numbers->next('production_order',(int)$data['location_id']),'order_date'=>$data['order_date'],'due_date'=>$data['due_date']??null,'artisan_id'=>$data['artisan_id']??null,'supplier_contact_id'=>$data['supplier_contact_id']??null,'customer_contact_id'=>$data['customer_contact_id']??null,'status'=>'draft','priority'=>$data['priority'],'instructions'=>$data['instructions']??null,'estimated_cost'=>$data['estimated_cost']??0]));foreach($data['lines'] as $line)$order->lines()->create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),$line));$this->audit->record('created',$order);return $order->load('lines');});}
 public function update(ProductionOrder $order,array $data):ProductionOrder{if($order->status!=='draft')throw new DomainException('Only draft production orders can be edited.');return DB::transaction(function()use($order,$data){$old=$order->getAttributes();$order->update(['order_date'=>$data['order_date'],'due_date'=>$data['due_date']??null,'location_id'=>$data['location_id'],'store_id'=>$data['store_id'],'artisan_id'=>$data['artisan_id']??null,'supplier_contact_id'=>$data['supplier_contact_id']??null,'customer_contact_id'=>$data['customer_contact_id']??null,'priority'=>$data['priority'],'instructions'=>$data['instructions']??null,'estimated_cost'=>$data['estimated_cost']??0]);$order->lines()->delete();foreach($data['lines'] as $line)$order->lines()->create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),$line));$this->audit->record('updated',$order,null,$old,$order->getAttributes());return $order->load('lines');});}
 public function approve(ProductionOrder $order):ProductionOrder{if($order->status!=='draft')throw new DomainException('Only draft production orders can be approved.');$order->update(['status'=>'approved','approved_by'=>RanContext::userId(),'approved_at'=>now()]);$this->audit->record('approved',$order);return $order;}
 public function issue(ProductionOrder $order,array $data):MaterialIssue{if(!in_array($order->status,['approved','in_progress'],true))throw new DomainException('Approve the production order before issuing material.');return DB::transaction(function()use($order,$data){$issue=MaterialIssue::create(array_merge(RanContext::scope(['location_id'=>$order->location_id,'store_id'=>$order->store_id]),['issue_no'=>$this->numbers->next('material_issue',$order->location_id),'issue_date'=>$data['issue_date'],'production_order_id'=>$order->id,'artisan_id'=>$order->artisan_id,'status'=>'posted','notes'=>$data['notes']??null]));foreach($data['lines'] as $line){$lot=StockLot::findOrFail($line['stock_lot_id']);$this->inventory->issue($lot,(float)$line['quantity'],(float)$line['net_weight'],['reference_type'=>'material_issue','reference_id'=>$issue->id,'reference_no'=>$issue->issue_no,'description'=>'Material issued to production']);$issue->lines()->create(array_merge(RanContext::scope(['location_id'=>$order->location_id,'store_id'=>$order->store_id]),['stock_lot_id'=>$lot->id,'item_id'=>$lot->item_id,'quantity'=>$line['quantity'],'gross_weight'=>$line['gross_weight']??$line['net_weight'],'net_weight'=>$line['net_weight'],'fine_weight'=>$line['fine_weight']??0,'unit_cost'=>$lot->unit_cost,'total_cost'=>(float)$lot->unit_cost*max((float)$line['quantity'],1),'notes'=>$line['notes']??null]));}$order->update(['status'=>'in_progress']);$this->audit->record('material_issued',$issue);return $issue->load('lines');});}
 public function receive(ProductionOrder $order,array $data):ProductionReceipt{return DB::transaction(function()use($order,$data){if(!in_array($order->status,['approved','in_progress'],true))throw new DomainException('This production order cannot receive finished goods.');$receipt=ProductionReceipt::create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),['receipt_no'=>$this->numbers->next('production_receipt',(int)$data['location_id']),'receipt_date'=>$data['receipt_date'],'production_order_id'=>$order->id,'artisan_id'=>$order->artisan_id,'status'=>'posted','labour_cost'=>$data['labour_cost']??0,'other_cost'=>$data['other_cost']??0,'notes'=>$data['notes']??null]));$count=max(count($data['lines']),1);$actual=0;foreach($data['lines'] as $line){$line['labour_cost']=(float)($data['labour_cost']??0)/$count;$line['other_cost']=(float)($data['other_cost']??0)/$count;$line['total_cost']=(float)($line['material_cost']??0)+$line['labour_cost']+$line['other_cost'];$lotNo=$line['lot_no']??null;$serialNo=$line['serial_no']??null;unset($line['lot_no'],$line['serial_no']);$receiptLine=$receipt->lines()->create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),$line));$this->inventory->receive(['item_id'=>$line['item_id'],'location_id'=>$data['location_id'],'store_id'=>$data['store_id'],'lot_no'=>$lotNo,'serial_no'=>$serialNo,'quantity'=>$line['quantity'],'gross_weight'=>$line['gross_weight']??0,'net_weight'=>$line['net_weight']??0,'stone_weight'=>$line['stone_weight']??0,'fine_weight'=>$line['fine_weight']??0,'unit_cost'=>$line['total_cost']/max((float)$line['quantity'],1),'total_cost'=>$line['total_cost'],'sale_price'=>$line['sale_price']??0,'source_type'=>'production_receipt','source_id'=>$receipt->id,'reference_no'=>$receipt->receipt_no,'description'=>'Finished jewellery received from production']);$actual+=$line['total_cost'];}$order->update(['status'=>'completed','actual_cost'=>$actual]);$this->audit->record('production_received',$receipt);return $receipt->load('lines');});}
 public function wastage(ProductionOrder $order,array $data):WastageEntry{$entry=WastageEntry::create(array_merge(RanContext::scope(['location_id'=>$order->location_id,'store_id'=>$order->store_id]),['entry_date'=>$data['entry_date']??now()->toDateString(),'production_order_id'=>$order->id,'material_issue_line_id'=>$data['material_issue_line_id']??null,'item_id'=>$data['item_id']??null,'entry_type'=>$data['entry_type'],'weight'=>$data['weight'],'fine_weight'=>$data['fine_weight']??0,'value'=>$data['value']??0,'reason'=>$data['reason']??null,'approved_by'=>RanContext::userId(),'approved_at'=>now()]));$this->audit->record('wastage_recorded',$entry);return $entry;}}
